static QByteArray bytes(const std::filesystem::path& path){QFile file(QString::fromStdWString(path.wstring()));require(file.open(QIODevice::ReadOnly),"read output");return file.readAll();}
static void reject(const QJsonObject& request,const std::filesystem::path& path){auto before=bytes(path);bool failed=false;try{writePreservedArchive(request,path);}catch(const ExchangeError&){failed=true;}require(failed&&before==bytes(path),"invalid native transform must reject atomically");}
