    nativeDefinition=ON_InstanceDefinition::Cast(editedCopy.nativeModel->ComponentFromId(ON_ModelComponent::Type::InstanceDefinition,definitionId).ModelComponent());nativeInstance=ON_InstanceRef::Cast(geometry(editedCopy,instanceId)->Geometry(nullptr));auto cloudBounds=editedCloud->BoundingBox();auto worldBounds=cloudBounds;worldBounds.Transform(nativeInstance->m_xform);require(nativeDefinition->BoundingBox().m_min.DistanceTo(cloudBounds.m_min)<1e-8&&nativeDefinition->BoundingBox().m_max.DistanceTo(cloudBounds.m_max)<1e-8&&nativeInstance->m_bbox.m_min.DistanceTo(worldBounds.m_min)<1e-8&&nativeInstance->m_bbox.m_max.DistanceTo(worldBounds.m_max)<1e-8,"retained member native delta refreshes definition and reference bounds");
