static void rationalCurveTransform(){
    ON_NurbsCurve source(2,true,3,3);source.SetCV(0,ON_4dPoint(0,0,0,1));source.SetCV(1,ON_4dPoint(4,6,0,2));source.SetCV(2,ON_4dPoint(2,-0.5,0,0.5));require(source.MakeClampedUniformKnotVector(1)&&source.IsValid(),"native rational2D transform fixture");
    ON_Xform matrix=ON_Xform::IdentityTransformation;matrix[0][0]=-2;matrix[1][1]=3;matrix[2][3]=9;auto curve=source;transformNativeGeometry(curve,matrix);require(curve.Dimension()==3&&curve.IsRational()&&curve.Order()==source.Order()&&curve.KnotCount()==source.KnotCount(),"out-of-plane rational2D transform explicitly promotes dimensions without changing basis");
    for(int i=0;i<curve.KnotCount();++i)require(curve.Knot(i)==source.Knot(i),"native promoted curve keeps exact knot vector");
    for(int i=0;i<curve.CVCount();++i){ON_3dPoint before,after;require(source.GetCV(i,before)&&curve.GetCV(i,after)&&(matrix*before).DistanceTo(after)<1e-10&&curve.Weight(i)==source.Weight(i),"native promoted curve keeps exact weights and analytic3D control points");}
    ONX_Model model;model.m_settings.m_ModelUnitsAndTolerances.m_unit_system=ON_UnitSystem(ON::LengthUnitSystem::Millimeters);ON_Layer layer;layer.SetName(L"Rational plane");model.AddModelComponent(layer);ON_3dmObjectAttributes attributes;attributes.SetMode(ON::idef_object);auto member=model.AddModelGeometryComponent(&source,&attributes);ON_InstanceDefinition definition;definition.SetName(L"Rational2D plane");definition.AddInstanceGeometryId(member.ModelComponent()->Id());auto target=model.AddModelComponent(definition);ON_InstanceRef instance;instance.m_instance_definition_uuid=target.ModelComponent()->Id();instance.m_xform=matrix;attributes.SetMode(ON::normal_object);model.AddModelGeometryComponent(&instance,&attributes);auto path=std::filesystem::temp_directory_path()/"om9-native-rational-plane.3dm";require(model.Write(path.c_str(),5,nullptr),"rational plane fixture write");auto archive=readArchive(path);require(archive.items.size()==1,"rational block geometry-only expansion");BRepAdaptor_Curve expanded(TopoDS::Edge(std::get<TopoDS_Shape>(archive.items[0].geometry)));auto expected=matrix*source.PointAt(0.5);require(expanded.Value(0.5).Distance(gp_Pnt(expected.x,expected.y,expected.z))<1e-9,"geometry-only2D rational block transform retains out-of-plane point");
    matrix[2][3]=0;auto planar=source;transformNativeGeometry(planar,matrix);require(planar.Dimension()==2,"plane-preserving native curve copy retains2D dimension");require(source.Dimension()==2,"native source curve remains immutable");
}
